import { DualValueSeriesOptions } from "../series";
import { DualValueChartOptions } from "../definitions";
/**
 * Options for a bubble chart series.
 * @group Charts
 * @category Bubble Chart
 */
export interface BubbleChartSeriesOptions extends DualValueSeriesOptions {
    /**
     * The field in the data source that contains the value for the bubble's size.
     */
    valueField: string;
}
/**
 * Options for a bubble chart.
 * @group Charts
 * @category Bubble Chart
 */
export interface BubbleChartOptions extends DualValueChartOptions {
    /**
     * The minimum size (in pixels) for a bubble. Defaults to 10.
     */
    minPointSize?: number;
    /**
     * The maximum size (in pixels) for a bubble. No default.
     */
    maxPointSize?: number;
    /**
     * An array of bubble chart series options.
     */
    series: Array<BubbleChartSeriesOptions>;
}
